//! 🧵️ Accepted press emission lanes remain in their original recipient through funded move-only settlement.
use super::*;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_tool_machine::{OriginalScrubRequest,OriginalScrubWrite,ScrubInput};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueRefusalKind};
use std::mem::size_of;
type Leaf<A> = PressLeaf<<A as ArtifactApp>::Mutation,<A as ArtifactApp>::ConfigMutation>;
#[derive(semio_framework_value::RetireOwned)]
struct Owners<M,CM>{window:Option<String>,tool:Option<String>,actor:Option<protocol::ActorId>,base:Option<String>,clock:Option<HybridLogicalTimestamp>,request:Option<OriginalScrubRequest<PressLeaf<M,CM>>>,leaves:Vec<PressLeaf<M,CM>>,gesture:Option<String>,previous:Option<protocol::TransactionRef>,output:Option<ToolStep<PressLeaf<M,CM>>>,empty:Option<Vec<PressLeaf<M,CM>>>}
pub struct OriginalPressSettlement<A:ArtifactApp>{source_binding:OriginalSourceBinding,source_decoder:(u64,u64),binding:Option<OriginalSourceBinding>,decoder:Option<(u64,u64)>,actor:(usize,usize),base:[u8;32],backing:[(usize,usize);4],lengths:[usize;4],phase:u8,lane:usize,index:usize,mode:u8,reason:ToolAbortReason,result:bool,closing:bool,writer:Option<Box<OriginalScrubWrite<Leaf<A>>>>,owners:ControlledRetirement<Owners<A::Mutation,A::ConfigMutation>>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original press settlement changed its retained emission or source")}
fn move_demand(bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn paid(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce()->Result<(),ValueError>)->Result<bool,OriginalTurnFailure>{let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{run()?;Ok(((),receipt(d)))})}
fn child_grant(cx:&StepContext<'_>,d:RetirementDemand,extra:usize)->Option<RetainedCloneGrant>{let g=cx.retained_grant();let copy=d.copy_bytes.checked_add(extra)?;if cx.should_yield()||cx.is_cancelled()||g.maximum_items==0||g.maximum_copy_bytes<copy||g.maximum_capacity_bytes<d.capacity_bytes||g.maximum_release_bytes<d.release_bytes||g.maximum_depth<d.depth{return None}Some(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-extra,..g})}
fn post_header(cx:&mut StepContext<'_>,bytes:usize)->Result<(),OriginalTurnFailure>{cx.consume_retained(RetainedCloneProgress{copied_bytes:bytes,..Default::default()})?;Ok(())}
fn backing<M,CM,D>(emit:&Emit<M,CM,D>)->[(usize,usize);4]{[(emit.artifact_mutations.as_ptr()as usize,emit.artifact_mutations.capacity()),(emit.child_emits.as_ptr()as usize,emit.child_emits.capacity()),(emit.config_mutations.as_ptr()as usize,emit.config_mutations.capacity()),(emit.window_config_mutations.as_ptr()as usize,emit.window_config_mutations.capacity())]}
fn lengths<M,CM,D>(emit:&Emit<M,CM,D>)->[usize;4]{[emit.artifact_mutations.len(),emit.child_emits.len(),emit.config_mutations.len(),emit.window_config_mutations.len()]}
impl<A:ArtifactApp> OriginalPressSettlement<A>{
 pub fn admit<D>(base:&[u8;32],actor:&str,emit:&mut Emit<A::Mutation,A::ConfigMutation,D>,tag_copy_bytes:usize,receive:impl FnOnce()->(ScrubTag,HybridLogicalTimestamp),cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{
  if output.is_some(){return Err(invalid().into())}let lengths=lengths(emit);let count=lengths.iter().try_fold(0usize,|n,v|n.checked_add(*v)).ok_or_else(invalid)?;
  let capacity=size_of::<Self>().checked_add(count.checked_mul(size_of::<Leaf<A>>()).ok_or_else(invalid)?).and_then(|n|n.checked_add(actor.len())).and_then(|n|n.checked_add(64)).ok_or_else(invalid)?;
  let d=RetirementDemand{copy_bytes:2*size_of::<Self>()+2*size_of::<ScrubTag>()+actor.len()+64+size_of::<u64>()+tag_copy_bytes,capacity_bytes:capacity,depth:1,..Default::default()};let binding=OriginalSourceBinding::borrow(cx);let actor_identity=(actor.as_ptr()as usize,actor.len());let backing=backing(emit);
  admit_original_construction(cx,output,original(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);let mut encoded=String::with_capacity(64);for byte in base{encoded.push(b"0123456789abcdef"[usize::from(byte>>4)]as char);encoded.push(b"0123456789abcdef"[usize::from(byte&15)]as char)}let mut actor_text=String::with_capacity(actor.len());actor_text.push_str(actor);let(ScrubTag{window,tool,phase},clock)=receive();let(mode,gesture,reason)=match phase{ScrubPhase::Tick{gesture}=>(0,gesture,ToolAbortReason::Tool),ScrubPhase::Commit{gesture}=>(1,gesture,ToolAbortReason::Tool),ScrubPhase::Abort{gesture,reason}=>(2,gesture,reason)};
   let metadata_capacity=actor_text.capacity()+encoded.capacity();let owners=Owners{window:Some(window),tool:Some(tool),actor:Some(protocol::ActorId(actor_text.into())),base:Some(encoded),clock:Some(clock),request:None,leaves:Vec::with_capacity(count),gesture:Some(gesture),previous:emit.transaction.take(),output:None,empty:None};
   let actual=size_of::<Self>()+owners.leaves.capacity()*size_of::<Leaf<A>>()+metadata_capacity;let mut p=receipt(d);p.retained_capacity_bytes=actual;
   Ok((Box::new(Self{source_binding:binding,source_decoder:decoder,binding:Some(binding),decoder:Some(decoder),actor:actor_identity,base:*base,backing,lengths,phase:0,lane:0,index:0,mode,reason,result:false,closing:false,writer:None,owners:ControlledRetirement::retain(owners)}),p))})
 }
 pub fn matches_context(&self,cx:&StepContext<'_>)->bool{self.source_binding.matches(cx)&&Some(self.source_decoder)==cx.native_receiving_identity()}
 pub fn accepts<D>(&self,base:&[u8;32],actor:&str,emit:&Emit<A::Mutation,A::ConfigMutation,D>)->bool{self.actor==(actor.as_ptr()as usize,actor.len())&&self.base==*base&&self.backing==backing(emit)&&self.lengths==lengths(emit)}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if !self.binding.is_some_and(|b|b.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(invalid())}Ok(())}
 pub fn advance<D>(&mut self,ledger:&mut ScrubLedger<Leaf<A>>,base:&[u8;32],actor:&str,emit:&mut Emit<A::Mutation,A::ConfigMutation,D>,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{
  self.validate(cx)?;if !self.accepts(base,actor,emit){return Err(invalid().into())}if self.closing||cx.is_cancelled(){self.close_step(ledger,cx)?;return Ok(())}
  if self.phase>=8{self.close_step(ledger,cx)?;return Ok(())}
  let owners=self.owners.original_mut().ok_or_else(invalid)?;
  if self.phase==0{let d=move_demand(2*size_of::<Leaf<A>>()+2*size_of::<usize>());paid(cx,d,||{let leaf=match self.lane{0=>emit.window_config_mutations.pop().map(PressLeaf::WindowConfig),1=>emit.config_mutations.pop().map(PressLeaf::Config),2=>emit.child_emits.pop().map(PressLeaf::Child),3=>emit.artifact_mutations.pop().map(PressLeaf::Member),_=>None};if let Some(leaf)=leaf{owners.leaves.push(leaf);self.lengths[3-self.lane]-=1}else{self.lane+=1;if self.lane==4{self.phase=1;self.index=0}}Ok(())})?;return Ok(())}
  if self.phase==1{let d=move_demand(2*size_of::<Leaf<A>>()+size_of::<usize>());paid(cx,d,||{if self.index<owners.leaves.len()/2{let end=owners.leaves.len()-self.index-1;owners.leaves.swap(self.index,end);self.index+=1}else{self.phase=2}Ok(())})?;return Ok(())}
  if self.phase==2{let d=move_demand(2*size_of::<ScrubInput<Leaf<A>>>()+2*size_of::<Vec<Leaf<A>>>());paid(cx,d,||{let input=match self.mode{0=>ScrubInput::Tick{gesture:owners.gesture.take().unwrap(),leaves:std::mem::take(&mut owners.leaves)},1=>ScrubInput::Commit{gesture:owners.gesture.take().unwrap(),leaves:std::mem::take(&mut owners.leaves)},_=>ScrubInput::Abort{reason:self.reason}};owners.request=Some(OriginalScrubRequest::Value{window:owners.window.take().unwrap(),tool:owners.tool.take().unwrap(),actor:owners.actor.take().unwrap(),base_revision:owners.base.take().unwrap(),clock:owners.clock.take().unwrap(),input:Some(input)});self.phase=3;Ok(())})?;return Ok(())}
  if self.phase==3{let extra=size_of::<u8>();let d=OriginalScrubWrite::admission_demands(ledger,owners.request.as_ref().ok_or_else(invalid)?)?;let Some(grant)=child_grant(cx,d,extra)else{return Ok(())};if cx.with_retained_loan(grant,|same|OriginalScrubWrite::admit(ledger,&mut owners.request,&mut self.writer,same))?{post_header(cx,extra)?;self.phase=4}return Ok(())}
  if self.phase==4{let extra=size_of::<u8>()+size_of::<bool>();let writer=self.writer.as_mut().ok_or_else(invalid)?;let d=writer.demands(ledger,cx.retained_grant().maximum_copy_bytes.saturating_sub(extra))?;let Some(grant)=child_grant(cx,d,extra)else{return Ok(())};if cx.with_retained_loan(grant,|same|writer.advance(ledger,&mut owners.output,same))?{post_header(cx,extra)?;self.result=matches!(owners.output,Some(ToolStep::Committed(..)));self.phase=5}return Ok(())}
  if self.phase==5{let d=move_demand(2*size_of::<Leaf<A>>()+size_of::<usize>());paid(cx,d,||{let Some(ToolStep::Committed(_,leaves))=owners.output.as_mut()else{self.phase=7;return Ok(())};let Some(last)=leaves.last()else{self.phase=6;self.lane=0;self.index=0;return Ok(())};let lane=match last{PressLeaf::Member(_)=>0,PressLeaf::Child(_)=>1,PressLeaf::Config(_)=>2,PressLeaf::WindowConfig(_)=>3};if self.lengths[lane]>=self.backing[lane].1{return Err(invalid())}match leaves.pop().unwrap(){PressLeaf::Member(v)=>emit.artifact_mutations.push(v),PressLeaf::Child(v)=>emit.child_emits.push(v),PressLeaf::Config(v)=>emit.config_mutations.push(v),PressLeaf::WindowConfig(v)=>emit.window_config_mutations.push(v)}self.lengths[lane]+=1;Ok(())})?;return Ok(())}
  if self.phase==6{let d=move_demand(2*size_of::<Leaf<A>>()+2*size_of::<usize>());paid(cx,d,||{let length=self.lengths[self.lane];if self.index<length/2{let end=length-self.index-1;match self.lane{0=>emit.artifact_mutations.swap(self.index,end),1=>emit.child_emits.swap(self.index,end),2=>emit.config_mutations.swap(self.index,end),_=>emit.window_config_mutations.swap(self.index,end)}self.index+=1}else{self.lane+=1;self.index=0;if self.lane==4{self.phase=7}}Ok(())})?;return Ok(())}
  let d=move_demand(2*size_of::<ToolStep<Leaf<A>>>()+2*size_of::<Option<protocol::TransactionRef>>());paid(cx,d,||{if self.result&&(!emit.artifact_mutations.is_empty()||!emit.child_emits.is_empty()){let Some(ToolStep::Committed(transaction,leaves))=owners.output.take()else{return Err(invalid())};emit.transaction=Some(transaction);owners.empty=Some(leaves)}self.phase=8;Ok(())})?;Ok(())
 }
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(writer)=self.writer.as_ref(){return if writer.terminal_is_empty(){Ok(writer.shell_close_demands())}else{writer.close_demands(body)}}if !self.owners.terminal_is_empty(){return self.owners.next_demand(body)}Ok(move_demand(size_of::<Option<OriginalSourceBinding>>()+size_of::<Option<(u64,u64)>>()+size_of::<bool>()))}
 pub fn close_step(&mut self,ledger:&mut ScrubLedger<Leaf<A>>,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(())}self.validate(cx)?;let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;if let Some(writer)=self.writer.as_mut(){if !writer.terminal_is_empty(){writer.close_step(ledger,cx)?;return Ok(())}close_original_retained_step(cx,d,|_|{self.writer.take();Ok(RetainedCloneStep::Progress(receipt(d)))})?;return Ok(())}if !self.owners.terminal_is_empty(){close_original_retained_step(cx,d,|g|self.owners.step(g))?;return Ok(())}close_original_retained_step(cx,d,|_|{self.binding=None;self.decoder=None;self.closing=true;Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.binding.is_none()&&self.writer.is_none()&&self.owners.terminal_is_empty()}
 pub fn result(&self)->bool{self.result}
 pub fn shell_close_demands(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<Self>>>(),release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl<A:ArtifactApp> Drop for OriginalPressSettlement<A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original press settlement requires its paid source close")}}
